#!/usr/bin/env bash
# Fetch the test audio for the Silero golden test (Silero's own example file,
# via the silero-vad-rust repo at a pinned commit, verified by SHA-256).
# The reference probabilities are a committed fixture generated by
# scripts/gen-golden-official.py with the official model + onnxruntime.
set -euo pipefail
cd "$(dirname "$0")/.."
REV=daa349430048ed07c35c1b62ccb4733c62306da2
BASE="https://raw.githubusercontent.com/huanglizhuo/silero-vad-rust/$REV/assets"
mkdir -p testdata/golden
fetch() {
  local name=$1 sum=$2 out=testdata/golden/$1
  if [ ! -f "$out" ] || ! echo "$sum  $out" | sha256sum -c --quiet - 2>/dev/null; then
    curl -fsSL "$BASE/$name" -o "$out"
  fi
  echo "$sum  $out" | sha256sum -c -
}
fetch aepyx.wav a622cb1cdd8a52db84b0d4bb524fa9a93f9ed387de40530f87c3a57d7493fd49
